# ORF finder: both strands, all frames, min 60 aa, ATG/GTG/TTG starts
seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()
comp = str.maketrans("ACGT", "TGCA")
rc = seq.translate(comp)[::-1]

table11 = {}
bases = "TCAG"
aas = "FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
i = 0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            table11[b1+b2+b3] = aas[i]
            i += 1

def orfs(s, frame_offset_label="f"):
    res = []
    for strand, ss in [("+", s), ("-", rc)]:
        for frame in range(3):
            i = frame
            while i < len(ss)-2:
                codon = ss[i:i+3]
                if codon in ("ATG","GTG","TTG"):
                    j = i
                    prot = []
                    while j < len(ss)-2:
                        aa = table11[ss[j:j+3]]
                        if aa == "*":
                            break
                        prot.append(aa)
                        j += 3
                    if len(prot) >= 60:
                        # map to original coords
                        if strand == "+":
                            gs, ge_ = i+1, j+2
                        else:
                            gs = len(s) - j
                            ge_ = len(s) - i
                        res.append((strand, ge_, gs, len(prot), "".join(prot)))
                        i = j
                        continue
                i += 3
    return res

os_ = orfs(seq)
os_.sort(key=lambda x: x[1])
print("ORFs >=60 aa (strand, start, end, len_aa):")
for strand, s, e, n, p in os_:
    print(f"{strand} {s:5d}..{e:5d}  {n}aa")
    print("   ", p[:100])
